h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: var(--font-weight-semibold);
  color: var(--color-espresso);
  line-height: var(--line-height-tight);
  letter-spacing: -0.01em;
}

h1 { font-size: clamp(2rem, 4vw, var(--font-size-5xl)); }
h2 { font-size: clamp(1.75rem, 3vw, var(--font-size-3xl)); }
h3 { font-size: clamp(1.35rem, 2.5vw, var(--font-size-2xl)); }
h4 { font-size: var(--font-size-xl); }
h5 { font-size: var(--font-size-lg); }
h6 { font-size: var(--font-size-base); }

p {
  color: var(--text-secondary);
  line-height: var(--line-height-relaxed);
  margin-bottom: var(--space-md);
}

p:last-child {
  margin-bottom: 0;
}

/* Layout Containers */
.container {
  width: 100%;
  max-width: var(--container-max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: var(--container-padding);
  padding-right: var(--container-padding);
}

.container-narrow {
  width: 100%;
  max-width: var(--container-narrow-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: var(--container-padding);
  padding-right: var(--container-padding);
}

/* Page Section Wrappers */
.section {
  padding-top: var(--space-3xl);
  padding-bottom: var(--space-3xl);
}

.section-sm {
  padding-top: var(--space-xl);
  padding-bottom: var(--space-xl);
}

.section-latte {
  background-color: var(--color-latte-soft);
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.section-espresso {
  background-color: var(--color-espresso);
  color: var(--color-cream);
}

.section-espresso h1,
.section-espresso h2,
.section-espresso h3,
.section-espresso h4 {
  color: var(--color-cream);
}

.section-espresso p {
  color: var(--color-latte);
}

/* Section Header Typography */
.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto var(--space-2xl) auto;
}

.section-eyebrow {
  display: inline-block;
  font-family: var(--font-sans);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-caramel);
  margin-bottom: var(--space-xs);
}

.section-title {
  margin-bottom: var(--space-sm);
}

.section-subtitle {
  font-size: var(--font-size-lg);
  color: var(--text-muted);
}

/* Grids */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .grid-4, .grid-3, .grid-2 {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }
  .section {
    padding-top: var(--space-2xl);
    padding-bottom: var(--space-2xl);
  }
}
